const item = $input.first();

const audio = item.binary?.audio;
const modo = item.json.body?.modo ?? "dictado";

return [{
  json: {
    ok: Boolean(audio),
    mensaje: audio
      ? "Audio recibido correctamente"
      : "No se encontró el archivo de audio",
    modo,
    archivo: audio?.fileName ?? null,
    campos_binarios: Object.keys(item.binary ?? {}),
    t0: Date.now()
  },
  binary: item.binary
}];

const stt = $input.first().json;
const modo = $('Validar recepción').first().json.modo;

const segmentos = [];
const etiquetas = {};

for (const w of stt.words ?? []) {
  if (w.type === 'audio_event') continue;

  if (w.type === 'spacing') {
    if (segmentos.length > 0) {
      segmentos[segmentos.length - 1].texto += w.text;
    }
    continue;
  }

  const speakerId = modo === 'consulta'
    ? (w.speaker_id ?? 'speaker_0')
    : 'speaker_0';

  if (!etiquetas[speakerId]) {
    etiquetas[speakerId] =
      `HABLANTE_${Object.keys(etiquetas).length + 1}`;
  }

  const hablante = etiquetas[speakerId];
  const ultimo = segmentos[segmentos.length - 1];

  if (ultimo && ultimo.hablante === hablante) {
    ultimo.texto += w.text;
    ultimo.fin = w.end;
  } else {
    segmentos.push({
      hablante,
      texto: w.text,
      inicio: w.start,
      fin: w.end
    });
  }
}

for (const s of segmentos) {
  s.texto = s.texto.trim();
}

const texto = stt.text ??
  segmentos.map(s => s.texto).join(' ');

if (!texto.trim()) {
  throw new Error('Transcripción vacía');
}

if (segmentos.length === 0) {
  segmentos.push({
    hablante: 'HABLANTE_1',
    texto,
    inicio: 0,
    fin: stt.audio_duration_secs ?? null
  });
}

const transcripcionParaLLM = segmentos
  .map(s => `${s.hablante}: ${s.texto}`)
  .join('\n');

return [{
  json: {
    transcripcion: {
      texto,
      segmentos
    },
    transcripcion_para_llm: transcripcionParaLLM,
    duracion_audio_s: stt.audio_duration_secs ?? null,
    t1: Date.now()
  }
}];

const respuesta = $input.first().json;
const formato = $('Formatear segmentos').first().json;

// Verificar respuesta de Backboard
if (respuesta.status !== 'COMPLETED') {
  throw new Error('La extracción de Backboard no se completó');
}

if (typeof respuesta.content !== 'string') {
  throw new Error('Backboard no devolvió contenido de texto');
}

// Limpiar posibles bloques Markdown
const contenido = respuesta.content
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// Convertir respuesta a JSON
let extraccion;

try {
  extraccion = JSON.parse(contenido);
} catch (error) {
  throw new Error('Backboard devolvió JSON inválido');
}

// Comprobar estructura mínima
if (
  !extraccion ||
  typeof extraccion !== 'object' ||
  Array.isArray(extraccion) ||
  !extraccion.secciones ||
  typeof extraccion.secciones !== 'object' ||
  !extraccion.hablantes ||
  typeof extraccion.hablantes !== 'object'
) {
  throw new Error('La extracción no cumple la estructura mínima');
}

// Tiempos medidos por el workflow
const t0 = $('Validar recepción').first().json.t0;
const t1 = formato.t1;

const msTranscripcion =
  typeof t0 === 'number' && typeof t1 === 'number'
    ? Math.max(0, t1 - t0)
    : null;

const msExtraccion =
  typeof t1 === 'number'
    ? Math.max(0, Date.now() - t1)
    : null;

// Contrato de respuesta para Django
return [{
  json: {
    transcripcion: formato.transcripcion,
    extraccion_raw: JSON.stringify(extraccion),
    metricas: {
      duracion_audio_s: formato.duracion_audio_s,
      ms_transcripcion: msTranscripcion,
      ms_extraccion: msExtraccion
    }
  }
}];
